<div class="heading"><div><h1>Mailbox administration</h1><p>Provisioning mode: <?= htmlspecialchars($providerName) ?></p></div></div><?php if ($error): ?><p class="alert"><?= htmlspecialchars($error) ?></p><?php endif; ?><?php if ($created): ?><section class="panel"><h2>Mailbox registered</h2><p><?= htmlspecialchars($created['email']) ?> · ID <?= (int)$created['id'] ?></p><p>Share this password with the mailbox owner through a secure channel. This notice is shown once.</p><label>Initial mailbox password<input readonly value="<?= htmlspecialchars($created['password']) ?>" onclick="this.select()"></label></section><?php endif; ?><section class="panel"><h2>Register a mailbox</h2><p class="muted">Manual mode: create it with CraneMail first, then register it here. CraneMail mode calls the configured API contract.</p><form method="post" action="/admin/mailboxes" class="grid"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><label>Member<select name="user_id" required><?php foreach ($members as $m): ?><option value="<?= (int)$m['id'] ?>"><?= htmlspecialchars($m['email']) ?></option><?php endforeach; ?></select></label><label>Mailbox local part<input name="local_part" required maxlength="64" pattern="[A-Za-z0-9._+-]+"><small>@ domain is configured in .env</small></label><label>Display name<input name="display_name" maxlength="120"></label><label>Mailbox password<input type="password" name="password" required minlength="12" autocomplete="new-password"></label><div><button type="submit">Register mailbox</button></div></form></section><section class="panel"><h2>Existing mailboxes</h2><?php if (!$mailboxes): ?><p>No mailboxes registered.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Mailbox</th><th>Owner</th><th>Provider</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach ($mailboxes as $m): ?><tr><td><?= htmlspecialchars($m['email']) ?></td><td><?= htmlspecialchars($m['owner_email']) ?></td><td><?= htmlspecialchars($m['provider']) ?></td><td><?= htmlspecialchars($m['status']) ?></td><td><?php if ($m['status']==='active' || $m['status']==='manual_pending'): ?><form method="post" action="/admin/mailboxes/<?= (int)$m['id'] ?>/suspend" data-confirm="<?= $providerName==='manual' ? 'Confirm that you have already suspended this mailbox in CraneMail?' : 'Suspend this mailbox at CraneMail?' ?>"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><?php if ($providerName==='manual'): ?><input type="hidden" name="confirm_external" value="yes"><?php endif; ?><button class="danger small">Confirm suspension</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
